import Foundation

/// Names as courts print them, read the way the platform reads them (`src/lib/courtNames.js`).
///
/// Courts print cause titles in capitals — "M/S PSTGEMS PRIVATE LIMITED VS. ALISHA ENTERPRISES".
/// The platform tidies such a title into title case, keeping the abbreviations Indian litigation
/// writes in capitals, and names a matter made from a tracked case with it. The Matters list
/// shows a tracked case under the same reading, so opening it as a matter does not rename it.
///
/// Held to the platform's own answers by `CourtNamesGolden` (generated by
/// `scripts/generate-court-name-fixtures.mjs`). JavaScript's `[A-Za-z]` and `\d` are
/// ASCII-only, and so is everything here.
enum CourtNames {
    static let keepCaps: Set<String> = [
        "UOI", "NCT", "GNCTD", "DDA", "MCD", "NDMC", "CBI", "ED", "NIA", "SBI", "RBI", "SEBI", "LIC", "NHAI",
        "ONGC", "BSES", "DMRC", "HDFC", "ICICI", "IDBI", "PNB", "BHEL", "NTPC", "GAIL", "IOCL", "BPCL", "HPCL",
        "AIIMS", "IIT", "UP", "MP", "HP", "J&K", "UT", "LLP", "HUF", "NGO", "CEO", "ITO", "CIT", "GST", "UK",
        "USA", "IT", "II", "III", "IV", "ANR.", "ORS.",
    ]
    static let smallWords: Set<String> = [
        "AND", "OF", "THE", "FOR", "IN", "AS", "TO", "BY", "ON", "AT", "OR", "THROUGH", "WITH",
    ]

    /// `title: true` reads a whole cause title: "vs." and its spellings become "v.", and the
    /// result is capped at 200 UTF-16 units as a matter's name is.
    static func tidy(_ raw: String?, title: Bool = false) -> String {
        let collapsed = (raw ?? "")
            .split(whereSeparator: { $0.isWhitespace })
            .joined(separator: " ")
        let words = collapsed.components(separatedBy: " ")
        let ups = words.map { $0.uppercased() }
        let explicit = ups.contains(where: isSeparator)

        func isVersus(_ i: Int) -> Bool {
            guard title else { return false }
            if isSeparator(ups[i]) { return true }
            return !explicit && isLoneV(ups[i]) && i > 0 && i < ups.count - 1 && !isBeforeInitial(ups[i - 1])
        }

        // Shouting is judged without the separators: courts write "vs." in lower case.
        let letters = words.indices
            .filter { !isSeparator(ups[$0]) && !isLoneV(ups[$0]) }
            .map { words[$0] }
            .joined()
            .filter { $0.isASCII && $0.isLetter }
        let shouting = letters.count > 3 && letters == letters.uppercased()

        let name = words.indices.map { i -> String in
            let word = words[i]
            let up = ups[i]
            if isVersus(i) { return "v." }
            if !shouting { return word }
            if up == "M/S" || up == "M/S." { return "M/s" }
            if up == "ANR." || up == "ANR" { return "Anr." }
            if up == "ORS." || up == "ORS" { return "Ors." }
            if i > 0, smallWords.contains(up) { return word.lowercased() }
            if keepCaps.contains(up) || word.contains(where: { $0.isASCII && $0.isNumber }) { return word }
            return titleCasedRuns(word)
        }
        .joined(separator: " ")

        guard title, name.utf16.count > 200 else { return name }
        let head = String(decoding: Array(name.utf16.prefix(197)), as: UTF16.self)
        return head + "…"
    }

    private static func isSeparator(_ up: String) -> Bool {
        ["VS", "VS.", "V/S", "V/S.", "VERSUS"].contains(up)
    }

    private static func isLoneV(_ up: String) -> Bool { up == "V" || up == "V." }

    /// A lone letter or a relation mark — "K." in "K. V. RAO", "S/O" in "S/O V. K. SHARMA".
    private static func isBeforeInitial(_ up: String) -> Bool {
        let chars = Array(up)
        if chars.count == 1 || (chars.count == 2 && chars[1] == ".") {
            return chars[0].isASCII && chars[0].isUppercase
        }
        let marks = ["S/O", "D/O", "W/O", "C/O"]
        return marks.contains(up) || marks.contains { up == $0 + "." }
    }

    /// Each run of ASCII letters (and apostrophes after the first) in title case, as `titleRun`
    /// reads it: single letters, the kept abbreviations, and a two-letter run not followed by a
    /// full stop or a hyphen stay as printed.
    private static func titleCasedRuns(_ word: String) -> String {
        let chars = Array(word)
        var out = ""
        var i = 0
        while i < chars.count {
            let c = chars[i]
            guard c.isASCII, c.isLetter else {
                out.append(c)
                i += 1
                continue
            }
            var j = i + 1
            while j < chars.count, (chars[j].isASCII && chars[j].isLetter) || chars[j] == "'" { j += 1 }
            let run = String(chars[i..<j])
            let next: Character? = j < chars.count ? chars[j] : nil
            out += titleRun(run, next: next)
            i = j
        }
        return out
    }

    private static func titleRun(_ run: String, next: Character?) -> String {
        if run.count == 1 || keepCaps.contains(run.uppercased()) { return run }
        if run.count == 2, next != ".", next != "-" { return run }
        return String(run.prefix(1)) + run.dropFirst().lowercased()
    }
}
